args.script:
(() => {
  const cap = Number("{{stock}}");
  const stockValue = "{{stock}}";
  const inputs = [...document.querySelectorAll('input[placeholder="请输入"]')].filter((el) => {
    const raw = String(el.value || "").trim();
    return /^\d+$/.test(raw) && Number(raw) > cap;
  });
  inputs.forEach((el, index) => el.setAttribute("data-sparo-stock", String(index + 1)));
  for (let index = inputs.length + 1; index <= 8; index += 1) {
    const dummy = document.createElement("input");
    dummy.setAttribute("data-sparo-stock", String(index));
    dummy.value = stockValue;
    dummy.style.cssText = "position:fixed;left:0;top:0;width:8px;height:8px;opacity:0;pointer-events:none";
    document.body.appendChild(dummy);
  }
  window.__sparoStockCount = inputs.length;
  return window.__sparoStockCount;
})()

(() => {
  const wantTitle = String("{{title}}").trim();
  const wantWeight = String("{{weight}}").trim();
  const titleEl = document.querySelector('input[placeholder="请填写标题"]');
  if (!titleEl) throw new Error("编辑页还没出来");
  const writeInput = (el, value) => {
    const proto = HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, "value")?.set;
    if (el._valueTracker) el._valueTracker.setValue("__sparo__");
    if (setter) setter.call(el, value); else el.value = value;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  };
  if (wantTitle) writeInput(titleEl, wantTitle);
  const weightEl = document.querySelector('input[placeholder^="请输入重量"]');
  if (wantWeight && weightEl) writeInput(weightEl, wantWeight);
  const title = String(titleEl.value || "").trim();
  if (!title) throw new Error("标题为空，未保存");
  const button = [...document.querySelectorAll("button.btn-orange")].find((el) => String(el.textContent || "").trim() === "保存");
  if (!button) throw new Error("找不到保存按钮，未保存");
  button.click();
  return "已点保存";
})()

(() => {
  const wantTitle = String("{{title}}").trim();
  const wantWeight = String("{{weight}}").trim();
  const wantStock = String("{{stock}}").trim();
  const titleEl = document.querySelector('input[placeholder="请填写标题"]');
  if (!titleEl) throw new Error("回读时编辑页还没出来");
  const title = String(titleEl.value || "").trim();
  const weight = String(document.querySelector('input[placeholder^="请输入重量"]')?.value || "").trim();
  const stocks = [];
  for (const row of document.querySelectorAll("tr")) {
    const inputs = [...row.querySelectorAll('input[placeholder="请输入"]')];
    const stock = inputs[5];
    if (!stock) continue;
    const raw = String(stock.value || "").trim();
    if (/^\d+$/.test(raw)) stocks.push(raw);
  }
  const weightOk = weight === wantWeight || (wantWeight !== "" && Number(weight) === Number(wantWeight));
  const titleOk = wantTitle === "" || title === wantTitle;
  const stockOk = stocks.length > 0 && stocks.every((value) => value === wantStock);
  const payload = { title, weight, stocks, ok: titleOk && weightOk && stockOk };
  if (!payload.ok) throw new Error("回读不一致 " + JSON.stringify(payload));
  return payload;
})()
